def _composite_rows(
    scenarios: list[str],
    elements: list[str],
    data: list,
    weights: list,
    min_elements: int,
) -> list[dict]:
    """Per-scenario composite stats in scenario order, without ranks."""
    n_scenarios = len(scenarios)
    n_elements = len(elements)

    rows = []
    for s_index, scenario in enumerate(scenarios):
        included = [
            (weights[e_index], data[e_index * n_scenarios + s_index])
            for e_index in range(n_elements)
            if weights[e_index] > 0
            and data[e_index * n_scenarios + s_index]["rank_count"] > 0
        ]
        covered = len(included)
        if covered < min_elements:
            rows.append(
                {
                    "scenario": scenario,
                    "covered": covered,
                    "mean": None,
                    "best": None,
                    "worst": None,
                    "u": None,
                }
            )
            continue
        # Divide the weights by the largest positive one and fsum-normalize
        # them into coefficients a (their fsum is 1); this keeps every
        # weight * rank / uncertainty product bounded even with extreme
        # weights.  The combined uncertainty is M * hypot(a * u / M) with M
        # the largest included uncertainty, so no intermediate term is
        # squared unscaled and the products cannot overflow.
        max_weight = max(weight for weight, _row in included)
        coeffs = [weight / max_weight for weight, _row in included]
        coeff_total = math.fsum(coeffs)
        coeffs = [coeff / coeff_total for coeff in coeffs]

        uncertainties = [row["uncertainty"] for _weight, row in included]
        max_u = max(uncertainties)
        if max_u == 0:
            combined_u = 0.0
        else:
            combined_u = max_u * math.hypot(
                *[
                    coeff * uncertainty / max_u
                    for coeff, uncertainty in zip(coeffs, uncertainties)
                ]
            )

        rows.append(
            {
                "scenario": scenario,
                "covered": covered,
                "mean": _round_output(
                    math.fsum(
                        coeff * row["mean_rank"]
                        for coeff, (_weight, row) in zip(coeffs, included)
                    )
                ),
                "best": min(row["best_rank"] for _weight, row in included),
                "worst": max(row["worst_rank"] for _weight, row in included),
                "u": _round_output(combined_u),
            }
        )
    return rows


def _rank_composite(
    scenarios: list[str],
    elements: list[str],
    data: list,
    weights: list,
    min_elements: int,
) -> list[dict]:
    """Composite rows sorted into rank order with ranks assigned."""
    rows = _composite_rows(scenarios, elements, data, weights, min_elements)

    valid = []
    invalid = []
    for row in rows:
        ranked = {**row, "rank": None}
        if row["mean"] is None:
            invalid.append(ranked)
        else:
            valid.append(ranked)

    # The sort is stable, so ties keep the original scenarios order.
    valid.sort(key=lambda row: row["mean"])
    for rank, row in enumerate(valid, start=1):
        row["rank"] = rank

    return valid + invalid

    total_items = len(items)
    data: list[dict] = []
    for scenario_index, scenario in enumerate(first_scenarios):
        totals: tuple[list, list] = ([], [])
        lower_bounds: tuple[list, list] = ([], [])
        upper_bounds: tuple[list, list] = ([], [])
        for rows in validated:
            row = rows[scenario_index]
            if row["total"] is None or row["interval"] is None:
                continue
            for column in range(2):
                totals[column].append(row["total"][column])
                lower_bounds[column].append(row["interval"][column][0])
                upper_bounds[column].append(row["interval"][column][1])

        valid = len(totals[0])
        missing = total_items - valid

        if valid < minimum:
            mean = None
            std = None
            band = None
        else:
            mean = []
            std = []
            band = []
            for column in range(2):
                values = totals[column]
                try:
                    mean_value = math.fsum(values) / valid
                    variance_value = (
                        math.fsum((value - mean_value) ** 2 for value in values)
                        / valid
                    )
                except OverflowError:
                    raise ValueError(
                        "compared total values must yield finite statistics"
                    ) from None
                std_value = math.sqrt(variance_value)
                if not _is_finite(mean_value) or not _is_finite(std_value):
                    raise ValueError(
                        "compared total values must yield finite statistics"
                    )
                mean.append(_round_output(mean_value))
                std.append(_round_output(std_value))
                band.append(
                    [
                        _round_output(min(lower_bounds[column])),
                        _round_output(max(upper_bounds[column])),
                    ]
                )

        data.append(
            {
                "scenario": scenario,
                "valid": valid,
                "missing": missing,
                "mean": mean,
                "std": std,
                "band": band,
            }
        )

    return {
        "schema": _GRADE_COMPARE_SCHEMA,
        "names": names,
        "pairs": [dict(pair) for pair in first_pairs],
        "scenarios": list(first_scenarios),
        "data": data,
    }


